import{_ as t,a0 as o,w as r,s as d,I as i,x as a,a1 as e,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Golang 的交叉編譯 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Golang 的交叉編譯 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Golang 的交叉編譯 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Golang 的交叉編譯 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210114 Cross-compiling made easy with Golang","title":"使用 Golang 的交叉編譯","tag":"202105","desc":""},"relativePath":"202105/20210114 Cross-compiling made easy with Golang.md","filePath":"[post].md"}'),h={name:"202105/20210114 Cross-compiling made easy with Golang.md"};function g(u,s,c,k,b,m){const n=o("Link");return r(),d("div",null,[s[24]||(s[24]=i("h1",{id:"使用-golang-的交叉編譯",tabindex:"-1"},[a("使用 Golang 的交叉編譯 "),i("a",{class:"header-anchor",href:"#使用-golang-的交叉編譯","aria-label":"Permalink to “使用 Golang 的交叉編譯”"},"​")],-1)),s[25]||(s[25]=i("blockquote",null,[i("p",null,"走出舒適區，我瞭解了 Go 的交叉編譯功能。")],-1)),s[26]||(s[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/13/092632nrg2z17i8vea4cf8.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=a("在 Linux 上測試軟件時，我使用各種架構的服務器，例如 Intel、AMD、Arm 等。當我 ",-1)),e(n,{href:"https://opensource.com/article/20/12/linux-server"},{default:l(()=>[...s[0]||(s[0]=[a("分配了一台滿足我的測試需求的 Linux 機器",-1)])]),_:1}),s[2]||(s[2]=a("，我仍然需要執行許多步驟：",-1))]),s[27]||(s[27]=p('<ol><li>下載並安裝必備軟件</li><li>驗證構建服務器上是否有新的測試軟件包</li><li>獲取並設置依賴軟件包所需的 yum 倉庫</li><li>下載並安裝新的測試軟件包（基於步驟 2）</li><li>獲取並設置必需的 SSL 證書</li><li>設置測試環境，獲取所需的 Git 倉庫，更改配置，重新啓動守護進程等</li><li>做其他需要做的事情</li></ol><h3 id="用腳本自動化" tabindex="-1">用腳本自動化 <a class="header-anchor" href="#用腳本自動化" aria-label="Permalink to “用腳本自動化”">​</a></h3><p>這些步驟非常常規，以至於有必要對其進行自動化並將腳本保存到中央位置（例如文件服務器），在需要時可以在此處下載腳本。為此，我編寫了 100-120 行的 Bash shell 腳本，它為我完成了所有配置（包括錯誤檢查）。這個腳本通過以下方式簡化了我的工作流程：</p><ol><li>配置新的 Linux 系統（支持測試的架構）</li><li>登錄系統並從中央位置下載自動化 shell 腳本</li><li>運行它來配置系統</li><li>開始測試</li></ol><h3 id="學習-go-語言" tabindex="-1">學習 Go 語言 <a class="header-anchor" href="#學習-go-語言" aria-label="Permalink to “學習 Go 語言”">​</a></h3>',5)),i("p",null,[s[4]||(s[4]=a("我想學習 ",-1)),e(n,{href:"https://golang.org/"},{default:l(()=>[...s[3]||(s[3]=[a("Go 語言",-1)])]),_:1}),s[5]||(s[5]=a(" 有一段時間了，將我心愛的 Shell 腳本轉換為 Go 程序似乎是一個很好的項目，可以幫助我入門。它的語法看起來很簡單，在嘗試了一些測試程序後，我開始着手提高自己的知識並熟悉 Go 標準庫。",-1))]),s[28]||(s[28]=p(`<p>我花了一個星期的時間在筆記本電腦上編寫 Go 程序。我經常在我的 x86 服務器上測試程序，清除錯誤並使程序健壯起來，一切都很順利。</p><p>直到完全轉換到 Go 程序前，我繼續依賴自己的 shell 腳本。然後，我將二進制文件推送到中央文件服務器上，以便每次配置新服務器時，我要做的就是獲取二進制文件，將可執行標誌打開，然後運行二進制文件。我對早期的結果很滿意：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://file.example.com/&lt;myuser&gt;/bins/prepnode</span></span>
<span class="line"><span>$ chmod  +x ./prepnode</span></span>
<span class="line"><span>$ ./prepnode</span></span></code></pre></div><h3 id="然後-出現了一個問題" tabindex="-1">然後，出現了一個問題 <a class="header-anchor" href="#然後-出現了一個問題" aria-label="Permalink to “然後，出現了一個問題”">​</a></h3><p>第二週，我從資源池中分配了一台新的服務器，像往常一樣，我下載了二進制文件，設置了可執行標誌，然後運行二進制文件。但這次它出錯了，是一個奇怪的錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./prepnode</span></span>
<span class="line"><span>bash: ./prepnode: cannot execute binary file: Exec format error</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>起初，我以為可能沒有成功設置可執行標誌。但是，它已按預期設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l prepnode</span></span>
<span class="line"><span>-rwxr-xr-x. 1 root root 2640529 Dec 16 05:43 prepnode</span></span></code></pre></div><p>發生了什麼事？我沒有對源代碼進行任何更改，編譯沒有引發任何錯誤或警告，而且上次運行時效果很好，因此我仔細查看了錯誤消息 <code>format error</code>。</p><p>我檢查了二進制文件的格式，一切看起來都沒問題：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file prepnode</span></span>
<span class="line"><span>prepnode: ELF 64-bit LSB executable, x86-64, version 1 (SYSV), statically linked, not stripped</span></span></code></pre></div><p>我迅速運行了以下命令，識別所配置的測試服務器的架構以及二進制試圖運行的平台。它是 Arm64 架構，但是我編譯的二進制文件（在我的 x86 筆記本電腦上）生成的是 x86-64 格式的二進制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -m</span></span>
<span class="line"><span>aarch64</span></span></code></pre></div><h3 id="腳本編寫人員的編譯第一課" tabindex="-1">腳本編寫人員的編譯第一課 <a class="header-anchor" href="#腳本編寫人員的編譯第一課" aria-label="Permalink to “腳本編寫人員的編譯第一課”">​</a></h3><p>在那之前，我從未考慮過這種情況（儘管我知道這一點）。我主要研究腳本語言（通常是 Python）以及 Shell 腳本。在任何架構的大多數 Linux 服務器上都可以使用 Bash Shell 和 Python 解釋器。總之，之前一切都很順利。</p>`,15)),i("p",null,[s[7]||(s[7]=a("但是，現在我正在處理 Go 這種編譯語言，它生成可執行的二進制文件。編譯後的二進制文件由特定架構的 ",-1)),e(n,{href:"https://en.wikipedia.org/wiki/Opcode"},{default:l(()=>[...s[6]||(s[6]=[a("指令碼",-1)])]),_:1}),s[8]||(s[8]=a(" 或彙編指令組成，這就是為什麼我收到格式錯誤的原因。由於 Arm64 CPU（運行二進制文件的地方）無法解釋二進制文件的 x86-64 指令，因此它拋出錯誤。以前，shell 和 Python 解釋器為我處理了底層指令碼或特定架構的指令。",-1))]),s[29]||(s[29]=p(`<h3 id="go-的交叉編譯" tabindex="-1">Go 的交叉編譯 <a class="header-anchor" href="#go-的交叉編譯" aria-label="Permalink to “Go 的交叉編譯”">​</a></h3><p>我檢查了 Golang 的文檔，發現要生成 Arm64 二進制文件，我要做的就是在運行 <code>go build</code> 命令編譯 Go 程序之前設置兩個環境變量。</p><p><code>GOOS</code> 指的是操作系統，例如 Linux、Windows、BSD 等，而 <code>GOARCH</code> 指的是要在哪種架構上構建程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ env GOOS=linux GOARCH=arm64 go build -o prepnode_arm64</span></span></code></pre></div><p>構建程序後，我重新運行 <code>file</code> 命令，這一次它顯示的是 ARM AArch64，而不是之前顯示的 x86。因此，我在我的筆記本上能為不同的架構構建二進制文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file prepnode_arm64</span></span>
<span class="line"><span>prepnode_arm64: ELF 64-bit LSB executable, ARM aarch64, version 1 (SYSV), statically linked, not stripped</span></span></code></pre></div><p>我將二進制文件從筆記本電腦複製到 ARM 服務器上。現在運行二進制文件（將可執行標誌打開）不會產生任何錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./prepnode_arm64  -h</span></span>
<span class="line"><span>Usage of ./prepnode_arm64:</span></span>
<span class="line"><span>  -c    Clean existing installation</span></span>
<span class="line"><span>  -n    Do not start test run (default true)</span></span>
<span class="line"><span>  -s    Use stage environment, default is qa</span></span>
<span class="line"><span>  -v    Enable verbose output</span></span></code></pre></div><h3 id="其他架構呢" tabindex="-1">其他架構呢？ <a class="header-anchor" href="#其他架構呢" aria-label="Permalink to “其他架構呢？”">​</a></h3><p>x86 和 Arm 是我測試軟件所支持的 5 種架構中的兩種，我擔心 Go 可能不會支持其它架構，但事實並非如此。你可以查看 Go 支持的架構：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ go tool dist list</span></span></code></pre></div><p>Go 支持多種平台和操作系統，包括：</p><ul><li>AIX</li><li>Android</li><li>Darwin</li><li>Dragonfly</li><li>FreeBSD</li><li>Illumos</li><li>JavaScript</li><li>Linux</li><li>NetBSD</li><li>OpenBSD</li><li>Plan 9</li><li>Solaris</li><li>Windows</li></ul><p>要查找其支持的特定 Linux 架構，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ go tool dist list | grep linux</span></span></code></pre></div><p>如下面的輸出所示，Go 支持我使用的所有體系結構。儘管 x86_64 不在列表中，但 AMD64 兼容 x86-64，所以你可以生成 AMD64 二進制文件，它可以在 x86 架構上正常運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ go tool dist list | grep linux</span></span>
<span class="line"><span>linux/386</span></span>
<span class="line"><span>linux/amd64</span></span>
<span class="line"><span>linux/arm</span></span>
<span class="line"><span>linux/arm64</span></span>
<span class="line"><span>linux/mips</span></span>
<span class="line"><span>linux/mips64</span></span>
<span class="line"><span>linux/mips64le</span></span>
<span class="line"><span>linux/mipsle</span></span>
<span class="line"><span>linux/ppc64</span></span>
<span class="line"><span>linux/ppc64le</span></span>
<span class="line"><span>linux/riscv64</span></span>
<span class="line"><span>linux/s390x</span></span></code></pre></div><h3 id="處理所有架構" tabindex="-1">處理所有架構 <a class="header-anchor" href="#處理所有架構" aria-label="Permalink to “處理所有架構”">​</a></h3><p>為我測試的所有體系結構生成二進制文件，就像從我的 x86 筆記本電腦編寫一個微小的 shell 腳本一樣簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/bash</span></span>
<span class="line"><span>archs=(amd64 arm64 ppc64le ppc64 s390x)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for arch in \${archs[@]}</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>        env GOOS=linux GOARCH=\${arch} go build -o prepnode_\${arch}</span></span>
<span class="line"><span>done</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file prepnode_*</span></span>
<span class="line"><span>prepnode_amd64:   ELF 64-bit LSB executable, x86-64, version 1 (SYSV), statically linked, Go BuildID=y03MzCXoZERH-0EwAAYI/p909FDnk7xEUo2LdHIyo/V2ABa7X_rLkPNHaFqUQ6/5p_q8MZiR2WYkA5CzJiF, not stripped</span></span>
<span class="line"><span>prepnode_arm64:   ELF 64-bit LSB executable, ARM aarch64, version 1 (SYSV), statically linked, Go BuildID=q-H-CCtLv__jVOcdcOpA/CywRwDz9LN2Wk_fWeJHt/K4-3P5tU2mzlWJa0noGN/SEev9TJFyvHdKZnPaZgb, not stripped</span></span>
<span class="line"><span>prepnode_ppc64:   ELF 64-bit MSB executable, 64-bit PowerPC or cisco 7500, version 1 (SYSV), statically linked, Go BuildID=DMWfc1QwOGIq2hxEzL_u/UE-9CIvkIMeNC_ocW4ry/r-7NcMATXatoXJQz3yUO/xzfiDIBuUxbuiyaw5Goq, not stripped</span></span>
<span class="line"><span>prepnode_ppc64le: ELF 64-bit LSB executable, 64-bit PowerPC or cisco 7500, version 1 (SYSV), statically linked, Go BuildID=C6qCjxwO9s63FJKDrv3f/xCJa4E6LPVpEZqmbF6B4/Mu6T_OR-dx-vLavn1Gyq/AWR1pK1cLz9YzLSFt5eU, not stripped</span></span>
<span class="line"><span>prepnode_s390x:   ELF 64-bit MSB executable, IBM S/390, version 1 (SYSV), statically linked, Go BuildID=faC_HDe1_iVq2XhpPD3d/7TIv0rulE4RZybgJVmPz/o_SZW_0iS0EkJJZHANxx/zuZgo79Je7zAs3v6Lxuz, not stripped</span></span></code></pre></div><p>現在，每當配置一台新機器時，我就運行以下 <code>wget</code> 命令下載特定體系結構的二進制文件，將可執行標誌打開，然後運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://file.domain.com/&lt;myuser&gt;/bins/prepnode_&lt;arch&gt;</span></span>
<span class="line"><span>$ chmod +x ./prepnode_&lt;arch&gt;</span></span>
<span class="line"><span>$ ./prepnode_&lt;arch&gt;</span></span></code></pre></div><h3 id="為什麼" tabindex="-1">為什麼？ <a class="header-anchor" href="#為什麼" aria-label="Permalink to “為什麼？”">​</a></h3><p>你可能想知道，為什麼我沒有堅持使用 shell 腳本或將程序移植到 Python 而不是編譯語言上來避免這些麻煩。所以有舍有得，那樣的話我不會了解 Go 的交叉編譯功能，以及程序在 CPU 上執行時的底層工作原理。在計算機中，總要考慮取捨，但絕不要讓它們阻礙你的學習。</p><hr>`,26)),i("p",null,[s[10]||(s[10]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/1/go-cross-compiling"},{default:l(()=>[...s[9]||(s[9]=[a("https://opensource.com/article/21/1/go-cross-compiling",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/gkamathe"},{default:l(()=>[...s[11]||(s[11]=[a("Gaurav Kamathe",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:l(()=>[...s[13]||(s[13]=[a("MjSeven",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[21]||(s[21]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const C=t(h,[["render",g]]);export{y as __pageData,C as default};
